// split_post.cjs  CommonJS版本，避开ESM路径bug
const fs = require('fs');
const path = require('path');

// 当前public目录，读取原始json
const inputPath = path.join(__dirname, 'position_skill_evolution.json');
const rawText = fs.readFileSync(inputPath, 'utf8');
const origin = JSON.parse(rawText);

const allPostObj = origin["岗位技能演变"];
const allPostKeys = Object.keys(allPostObj);

const part1Keys = allPostKeys.slice(0, 56);
const part2Keys = allPostKeys.slice(56);

// 保留顶层的生成说明
const part1 = { "生成说明": origin["生成说明"], "岗位技能演变": {} };
part1Keys.forEach(k => part1["岗位技能演变"][k] = allPostObj[k]);

const part2 = { "生成说明": origin["生成说明"], "岗位技能演变": {} };
part2Keys.forEach(k => part2["岗位技能演变"][k] = allPostObj[k]);

fs.writeFileSync('./position_skill_evolution_56.json', JSON.stringify(part1, null, 2), 'utf8');
fs.writeFileSync('./position_skill_evolution_remain.json', JSON.stringify(part2, null, 2), 'utf8');

console.log("✅拆分完成");
console.log("56岗位数量：", part1Keys.length);
console.log("剩余岗位数量：", part2Keys.length);
